SELECT item_stock_history.id AS id, item_info.id AS itemId, item_info.name AS itemName, item_stock_history.stock_before AS stockBefore, item_stock_history.amount_change AS amountChange, item_stock_history.stock_after AS stockAfter FROM item_stock_history LEFT JOIN item_info ON item_stock_history.item_id = item_info.id
item_stock_history.stock_history_id = #{stockHistoryId}
AND item_info.name LIKE CONCAT('%', #{itemName}, '%')
